import json
d=json.load(open('gestures.json'))
print(json.dumps(d.get('metadata',{}),indent=1)[:1500])
def walk(n,out):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t=='paragraph':
            sub=[];[walk(c,sub) for c in n.get('inlineContent',[])];out.append(''.join(sub)+'\n')
            return
        elif t=='heading': out.append('\n## '+n.get('text','')+'\n'); return
        for k,v in n.items():
            if k in ('text','code','type'): continue
            walk(v,out)
    elif isinstance(n,list):
        for c in n: walk(c,out)
out=[]
